window.__votdWeek && window.__votdWeek({"week":"2029-05-07","reading":"Doctrine and Covenants 45","days":[{"d":"2029-05-07","ref":"D&C 45:9","b":"D&C","c":45,"v":9,"he":"וְכֵן שָׁלַחְתִּי בְּרִיתִי אֲשֶׁר־לְעוֹלָם אֶל הָעוֹלָם לִהְיוֹת אוֹר לָעוֹלָם וְנֵס לְעַמִּי וְלַגּוֹיִם לִדְרֹשׁ אֵלֶיהָ וְלִהְיוֹת מַלְאָךְ לְפָנַי לְפַנּוֹת הַדֶּרֶךְ לְפָנָי׃","en":"And even so I have sent mine everlasting covenant into the world, to be a light to the world, and to be a standard for my people, and for the Gentiles to seek to it, and to be a messenger before my face to prepare the way before me."},{"d":"2029-05-08","ref":"D&C 45:25","b":"D&C","c":45,"v":25,"he":"אַךְ יֵאָסְפוּ שֵׁנִית אַךְ יִשָּׁאֲרוּ עַד מְלֹאת עִתּוֹת הַגּוֹיִם׃","en":"But they shall be gathered again; but they shall remain until the times of the Gentiles be fulfilled."},{"d":"2029-05-09","ref":"D&C 45:26","b":"D&C","c":45,"v":26,"he":"וּבַיּוֹם הַהוּא יִשָּׁמַע שֵׁמַע מִלְחָמוֹת וּשְׁמוּעוֹת מִלְחָמוֹת וְכׇל הָאָרֶץ תִּהְיֶה בִּמְהוּמָה וְלֵב אֲנָשִׁים יִמַּס וְיֹאמְרוּ כִּי הַמָּשִׁיחַ מְאַחֵר לָבוֹא עַד קֵץ הָאָרֶץ׃","en":"And in that day shall be heard of wars and rumors of wars, and the whole earth shall be in commotion, and men's hearts shall fail them, and they shall say that Christ delayeth his coming until the end of the earth."},{"d":"2029-05-10","ref":"D&C 45:29","b":"D&C","c":45,"v":29,"he":"אַךְ לֹא יְקַבְּלוּהָ כִּי לֹא יָבִינוּ הָאוֹר וְיָסִירוּ לְבָבָם מִמֶּנִּי בִּגְלַל מִצְוֹת אֲנָשִׁים׃","en":"But they receive it not; for they perceive not the light, and they turn their hearts from me because of the precepts of men."},{"d":"2029-05-11","ref":"D&C 45:41","b":"D&C","c":45,"v":41,"he":"וְיִרְאוּ דָּם וָאֵשׁ וְתִימְרוֹת עָשָׁן׃","en":"And they shall behold blood, and fire, and vapors of smoke."},{"d":"2029-05-12","ref":"D&C 45:58","b":"D&C","c":45,"v":58,"he":"וְהָאָרֶץ תִּנָּתֵן לָהֶם לְנַחֲלָה וְיִרְבּוּ וְיֶחֱזָקוּ וּבְנֵיהֶם יִגְדְּלוּ בְלֹא חֵטְא לִישׁוּעָה׃","en":"And the earth shall be given unto them for an inheritance; and they shall multiply and wax strong, and their children shall grow up without sin unto salvation."},{"d":"2029-05-13","ref":"D&C 45:59","b":"D&C","c":45,"v":59,"he":"כִּי יְהוָה יִהְיֶה בְתוֹכָם וּכְבוֹדוֹ יִהְיֶה עֲלֵיהֶם וְהוּא יִהְיֶה מַלְכָּם וּמְחֹקְקָם׃","en":"For the Lord shall be in their midst, and his glory shall be upon them, and he will be their king and their lawgiver."}]});
